import{_ as a,o as i,c as s,a3 as e}from"./chunks/framework.CVt6dz2a.js";const k=JSON.parse('{"title":"EP.28 把三维压成二维","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.28-flatten-3d.md","filePath":"comics/EP.28-flatten-3d.md","lastUpdated":1793881879000}'),d={name:"comics/EP.28-flatten-3d.md"};function l(o,t,r,n,h,p){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="ep-28-把三维压成二维" tabindex="-1">EP.28 把三维压成二维 <a class="header-anchor" href="#ep-28-把三维压成二维" aria-label="Permalink to &quot;EP.28 把三维压成二维&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/28-npr-stylized/basics">28.1 基础入门：描边（Outline）的四种做法</a> 延伸阅读：<a href="./../guide/28-npr-stylized/advanced">28.2 进阶应用：卡通着色与光照分级</a> · <a href="./../guide/28-npr-stylized/practice">28.3 实战案例：水墨与漫画风格渲染管线</a> 动手演示：<a href="./../public/demos/npr-stylized/outline-lab.html">outline-lab 描边四法对比台</a> · <a href="./../public/demos/npr-stylized/toon-ramp-lab.html">toon-ramp-lab 卡通着色分级台</a> · <a href="./../public/demos/npr-stylized/ink-wash-lab.html">ink-wash-lab 水墨渲染模式台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君把模型面数拉到极限，截图上却还是一片糊，物体之间没有边界；像素酱吐槽&quot;这哪是渲染，这是贴纸&quot;。</td></tr><tr><td>② 揭秘</td><td>码叔把连续光照切成三档，画出 ramp 采样链路：<code>ndl → 贴图 → 色阶</code>，并提醒暗部要加冷色，别用纯灰。</td></tr><tr><td>③ 实证</td><td>摆出四条描边路线：反向外壳、后处理边缘、菲涅尔、纹理描边，逐个标注成本与能画到的线。</td></tr><tr><td>④ 结案</td><td>三条纪律写进配置：风格参数集中管理、噪声必须连续、线宽按屏幕像素算；三种渲染模式做成可切换的开关。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-面数救不了风格-npr-是-读图说明书" tabindex="-1">① 面数救不了风格：NPR 是&quot;读图说明书&quot; <a class="header-anchor" href="#_1-面数救不了风格-npr-是-读图说明书" aria-label="Permalink to &quot;① 面数救不了风格：NPR 是&quot;读图说明书&quot;&quot;">​</a></h3><p>写实渲染靠光影、遮挡、景深把物体分开；一旦光照被压平，颜色相近的物体就会粘成一片。描边不是装饰，而是告诉观众&quot;这里是轮廓、那里是独立物件&quot;的说明书。<strong>所以 NPR 的第一课不是加细节，而是加边界与分级</strong>：少一点连续过渡，多一点明确色块。面数只影响轮廓的圆滑程度，不会自动产生&quot;画&quot;的感觉。</p><h3 id="_2-光照分级-把连续函数切成台阶" tabindex="-1">② 光照分级：把连续函数切成台阶 <a class="header-anchor" href="#_2-光照分级-把连续函数切成台阶" aria-label="Permalink to &quot;② 光照分级：把连续函数切成台阶&quot;">​</a></h3><p>Lambert 的 <code>ndl</code> 是 0 到 1 的连续值，卡通渲染把它映射到有限的几档：</p><table tabindex="0"><thead><tr><th>路径</th><th>做法</th><th>特点</th></tr></thead><tbody><tr><td>step 函数</td><td><code>floor(ndl * n) / n</code></td><td>无需贴图，档数由 uniform 控制</td></tr><tr><td>ramp 贴图</td><td>采样 256×1 的渐变图</td><td>边界、颜色、软硬都能由美术调</td></tr></tbody></table><div class="language-glsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">glsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vec3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ramp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> texture2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(uRamp, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vec2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ndl, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).rgb;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vec3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> col </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uBase </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ramp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">col </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uShadowTint </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ramp.r) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>ramp 用 RGB 三通道，暗部偏蓝、亮部偏暖，分级与调色一次完成。3 档是主流：亮、中间、暗刚好够读出体积；2 档更像海报，5 档更接近厚涂。高光也要用 <code>step</code> 切块，暗部则必须带一点冷色，纯灰会让画面&quot;灰死&quot;。</p><h3 id="_3-四条描边路线-先分清外轮廓与内部线" tabindex="-1">③ 四条描边路线：先分清外轮廓与内部线 <a class="header-anchor" href="#_3-四条描边路线-先分清外轮廓与内部线" aria-label="Permalink to &quot;③ 四条描边路线：先分清外轮廓与内部线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>做法</th><th>成本</th><th>能画到的线</th></tr></thead><tbody><tr><td>反向外壳</td><td>每物体 +1 draw call</td><td>只有外轮廓</td></tr><tr><td>后处理边缘</td><td>预渲染 + 1~2 个全屏 Pass</td><td>内外线都有</td></tr><tr><td>菲涅尔</td><td>零额外绘制</td><td>只有轮廓，随视角变</td></tr><tr><td>纹理描边</td><td>每像素 +4 次采样</td><td>内部结构线强，外轮廓弱</td></tr></tbody></table><p>反向外壳的关键是<strong>在裁剪空间外扩</strong>：<code>clip.xy += nView.xy * widthPx * 2.0 / resolution * clip.w</code>，用 <code>clip.w</code> 抵消透视的近大远小，线宽才稳定。后处理描边要先渲染法线与深度，再做 Sobel；深度要线性化，法线要 <code>* 2.0 - 1.0</code> 解码。菲涅尔是&quot;用亮度差模拟轮廓&quot;，最便宜但也最不稳定。纹理描边靠 UV 外扩比较法线差，能画出衣领、褶皱这类内部线。</p><h3 id="_4-组装管线-三种模式-五件事一起切" tabindex="-1">④ 组装管线：三种模式，五件事一起切 <a class="header-anchor" href="#_4-组装管线-三种模式-五件事一起切" aria-label="Permalink to &quot;④ 组装管线：三种模式，五件事一起切&quot;">​</a></h3><p>一条完整的水墨管线是：几何渲染 → 辅助缓冲（可选）→ 描边 → 去色与色阶 → 噪声阈值 → 纸纹与笔触 → 输出。两个铁律：<strong>描边必须在量化之前</strong>（否则色块边界会被误判成线）；<strong>整条链只做一次色调映射</strong>（统一交给 <code>OutputPass</code>）。</p><p>模式切换要同步改五件事：<code>mesh.material</code>、<code>renderer.toneMapping</code>、<code>scene.background</code>、<code>scene.fog</code>、<code>inkPass.enabled</code>。少改一项就会出现&quot;水墨模式里还挂着写实暖雾&quot;的违和。水墨的墨色分层用带噪声的窄区间 <code>smoothstep</code>，噪声不是叠在画面上，而是决定&quot;这个像素算哪一档&quot;，所以边界会自然长出毛边。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：卡通渲染暗部发灰发脏？</strong> 多半是软阴影的连续灰带混进了色阶，或暗部只做了变暗没加冷色。改硬边阴影，暗部叠 0.1~0.25 的冷色偏移。</li><li><strong>Q：外壳描边近粗远细？</strong> 用了世界单位外扩。改裁剪空间公式并乘 <code>clip.w</code>，resize 时同步 <code>uResolution</code> 与 <code>devicePixelRatio</code>。</li><li><strong>Q：后处理描边满屏短线与噪点？</strong> 检查深度精度、法线是否解码、搜索半径是否只有一像素；半径提到 2~3 像素并加阈值余量。</li><li><strong>Q：风格化后边缘一直闪？</strong> 单采样边缘检测 + 一像素线宽是主因；配 SMAA、加粗线宽、远处淡出。噪声必须连续，禁止每帧 <code>Math.random()</code>。</li><li><strong>Q：切换模式卡一下？</strong> shader 重编译。三份材质提前创建、切换只换引用，或用 <code>compileAsync</code> 预编译。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>反向外壳、后处理边缘、菲涅尔、纹理描边，各自能画外轮廓还是内部线？成本分别是什么？</li><li>为什么卡通渲染里软阴影反而让画面&quot;脏&quot;？应该怎么处理暗部？</li><li>水墨管线的正确顺序是什么？为什么描边必须放在量化之前？</li></ol><details><summary>答案</summary><ol><li>反向外壳只能画外轮廓，每物体多一次 draw call；后处理边缘内外线都能画，需要一次法线/深度预渲染加一至两次全屏 Pass；菲涅尔只能画外轮廓，零额外绘制，但线宽随视角变化；纹理描边擅长内部结构线，每像素多四次纹理采样，但描不到真正的物体外轮廓，通常与外壳搭配。</li><li>软阴影在亮部与暗部之间制造了一条连续灰带，这条灰带既不属于亮色阶也不属于暗色阶，视觉上就是&quot;脏&quot;。处理方式是改硬边阴影、减小模糊半径、去掉会撒灰的 SSAO，并给暗部叠加 0.1~0.25 的冷色偏移，避免纯灰。</li><li>顺序是：几何渲染 → 辅助缓冲（可选）→ 描边 → 去色与色阶 → 噪声阈值 → 纸纹与笔触 → 输出。描边必须在量化之前，因为量化会产生大量色块边界，边缘检测会把它们全部误判成线，结果是满屏墨；应在颜色还连续时找边，再把线压上去。</li></ol></details>`,23)])])}const u=a(d,[["render",l]]);export{k as __pageData,u as default};
